while getopts ":o:v" opt; do
  case "$opt" in
    o) output=$OPTARG ;;
    v) verbose=1 ;;
    :) printf '缺少参数: -%s\n' "$OPTARG" >&2; exit 2 ;;
    \?) printf '未知选项: -%s\n' "$OPTARG" >&2; exit 2 ;;
  esac
done
shift "$((OPTIND-1))"

